payload.template:
module tickgen #(parameter int N = 4) (
  input  logic clk,
  input  logic rst,
  output logic tick
);

  // This implementation is BROKEN: the ticks come N + 1 cycles apart
  // instead of N. The specification is in the problem statement, and
  // any implementation that meets it is accepted.

  logic [$clog2(N + 1):0] cnt;

  always_ff @(posedge clk) begin
    if (rst) begin
      cnt  <= '0;
      tick <= 1'b0;
    end else if (cnt == N) begin
      cnt  <= '0;
      tick <= 1'b1;
    end else begin
      cnt  <= cnt + 1'b1;
      tick <= 1'b0;
    end
  end

endmodule

payload.testbench:
`timescale 1ns/1ps

// The sample testbench. Run uses this one; Submit uses another that
// drives three values of N and resets in the middle of a period.
//
// Everything here is measured RELATIVELY: the gap between consecutive
// ticks and how wide a tick is. Nothing checks which edge the first
// tick lands on, because a registered output can legitimately place it
// a cycle either way and that is not what the exercise is about.
module tb;

  localparam int N = 4;

  logic clk = 1'b0;
  logic rst = 1'b1;
  logic tick;

  tickgen #(.N(N)) dut (.clk(clk), .rst(rst), .tick(tick));

  always #5 clk = ~clk;

  int e      = 0;    // rising edges since reset was released
  int t1     = -1;   // the edge each of the first three ticks was seen on
  int t2     = -1;
  int t3     = -1;
  int run    = 0;    // how many cycles the current tick has been high
  int widest = 0;
  int quiet  = 1;    // tick stayed low for as long as reset was high

  always @(posedge clk) begin
    if (rst) begin
      if (tick) quiet <= 0;
    end else begin
      e <= e + 1;
      if (tick) begin
        if      (t1 < 0) t1 <= e + 1;
        else if (t2 < 0) t2 <= e + 1;
        else if (t3 < 0) t3 <= e + 1;
        run    <= run + 1;
        widest <= (run + 1 > widest) ? run + 1 : widest;
      end else begin
        run <= 0;
      end
    end
  end

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    @(negedge clk);
    @(negedge clk);
    rst = 1'b0;

    repeat (24) @(posedge clk);
    #1;

    $display("CHECK quiet_in_reset 1 %0d AT %0d", quiet, $time);
    $display("CHECK ticks_seen 1 %0d AT %0d", (t3 > 0), $time);
    $display("CHECK period %0d %0d AT %0d", N, t2 - t1, $time);
    $display("CHECK period_again %0d %0d AT %0d", N, t3 - t2, $time);
    $display("CHECK one_cycle_wide 1 %0d AT %0d", widest, $time);
    $display("DONE 5");
    $finish;
  end

endmodule
